constexpr int64_t poww (int64_t a, int64_t p) {
    assert(p >= 0);
    int64_t res = 1;
    while (p > 0) {
        if (p & 1) res *= a;
        a *= a, p >>= 1;
    }
    return res;
}

constexpr int32_t path_len(const int32_t n) {
	return 1 + (n*n + n) / 2 - (n % 2 ? 0: n/2 - 1);
}

vector nums(0, 0ll);
vector walks(0, vector(0, 0));

void load_nums(const size_t p=10) {
	nums.resize(p * p);

	for (int i = 0; i < p; ++i)
		for (int j = 0; j < p; ++j)
			nums[i * 10 + j] = poww(2,(i+j)) * poww(3,i) * poww(5,j) * poww(7,(9-i)) * poww(11,(9-j));
}

void load_walks(const size_t max_k=100) {
	walks.resize(max_k + 1);
	walks[1] = vector({0, 0});
	walks[2] = vector({1, 1, 0, 0});

	for (int k = 3; k <= max_k; k++) {
		auto& walk = walks[k];
		walk = walks[k - 2];
		const int x = k-2, y = k-1;

		if (k % 2) {
			walk.push_back(x);
			walk.push_back(x);
			walk.push_back(y);
			walk.push_back(y);
			for (int j = 1; j < x; j += 2)
				walk.push_back(j),
				walk.push_back(x),
				walk.push_back(j+1),
				walk.push_back(y);
			walk.push_back(0);
		} else {
			walk.push_back(x);
			walk.push_back(x);
			walk.push_back(1);
			walk.push_back(y);
			walk.push_back(y);
			for (int j = 2; j < x; j += 2)
				walk.push_back(j),
				walk.push_back(x),
				walk.push_back(j+1),
				walk.push_back(y);
			walk.push_back(0);
		}
	}
}

void solve (const int kase) {

    int n; cin >> n;

    int l = 0, r = 100;
    while (l < r - 1) {
    	int m = r - (r-l) / 2;
    	if (path_len(m) < n)
    		l = m;
    	else
    		r = m;
    }

    vector a(n, 0ll);
    for (size_t i = 0; i < n; ++i) {
    	a[i] = nums[walks[r][i]];
    	cout << a[i] << ' ' ;
    }

    vector gcds(n-1, 0ll);
    for (size_t i = 1; i < n; ++i) {
    	gcds[i-1] = gcd(a[i], a[i - 1]);
    }

    assert(set(gcds.begin(), gcds.end()).size() == n-1);

    cout << '\n';
}

int main () {
    ios_base::sync_with_stdio(0), cin.tie(0);

    load_nums();
    load_walks();

    for (size_t i = 1 ; i < 101; ++i)
    	assert(walks[i].size() == path_len(i));

    int t; cin >> t, assert(t >= 0);
    for (int i = 0; t--; )
        solve(++i);

}
